import json, time, urllib.request, urllib.error, sys
BASE="http://localhost:8080"
tok=None
log=open("/tmp/recon/log.txt","a")
def token():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(BASE+"/token",method="POST",data=b""))
            tok=json.load(r)["token"]; log.write(f"TOKEN {tok}\n"); return
        except urllib.error.HTTPError as e:
            h=dict(e.headers); log.write(f"TOKEN ERR {e.code} {h} {e.read()[:200]}\n")
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(path, allow404=False):
    if tok is None: token()
    for attempt in range(200):
        req=urllib.request.Request(BASE+path,headers={"Authorization":f"Bearer {tok}"})
        try:
            r=urllib.request.urlopen(req,timeout=30)
            body=r.read()
            try: return json.loads(body)
            except Exception:
                log.write(f"BADJSON {path} {body[:200]}\n"); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body=e.read()[:300]; log.write(f"ERR {path} {e.code} {dict(e.headers)} {body}\n")
            if e.code==401 or e.code==403: token(); continue
            if e.code==404 and allow404: return None
            if e.code==429:
                ra=e.headers.get("Retry-After"); time.sleep(float(ra) if ra else 1); continue
            time.sleep(float(e.headers.get("Retry-After") or 0.5)); continue
        except Exception as e:
            log.write(f"EXC {path} {e!r}\n"); time.sleep(0.5)
    raise SystemExit("gave up "+path)
pages={}
path="/orders?page=1"
while path:
    d=get(path)
    pages[path]=d
    log.write(f"PAGE {path} page={d.get('page')} total={d.get('total_pages')} n={len(d.get('items',[]))} next={d.get('next')}\n"); log.flush()
    path=d.get("next")
json.dump(pages,open("/tmp/recon/pages.json","w"))
cids=sorted({o["customer_id"] for d in pages.values() for o in d["items"]})
custs={}
for c in cids:
    custs[c]=get(f"/customers/{c}",allow404=True)
json.dump(custs,open("/tmp/recon/customers.json","w"))
print(len(pages),"pages",len(cids),"customers")
EOF
cd /tmp/recon && rm -f log.txt && time python3 -I fetch.py

